--- a/platform/orchestration/actions/rerender_page_sections_action.go
+++ b/platform/orchestration/actions/rerender_page_sections_action.go
@@ -186,12 +186,25 @@
 	for _, s := range stored {
 		reason := ""
-		if len(s.contentData) == 0 {
-			reason = "no stored content_data"
-		} else if comp, ok := schemas[s.slotName]; ok && len(comp.InputSchema) > 0 {
-			if missing := missingRequiredLLMFields(comp.InputSchema, s.contentData); len(missing) > 0 {
-				reason = fmt.Sprintf("stored content_data missing required field(s) %v", missing)
-			}
-		}
+		comp, hasSchema := schemas[s.slotName]
+		// Does this component consume LLM-authored content AT ALL? Probe the
+		// contract with an empty map: missingRequiredLLMFields(schema, nil)
+		// returns exactly the required source:"llm" fields. If that is empty,
+		// the component renders wholly from its own template and empty
+		// content_data is its NORMAL shape, not the blanking hazard this
+		// pre-check exists for. Self-contained tools are that whole
+		// population (content_data = {}, no input_schema at all), and
+		// escalating them discards a perfectly good render.
+		if !hasSchema || len(missingRequiredLLMFields(comp.InputSchema, nil)) == 0 {
+			continue
+		}
+		if len(s.contentData) == 0 {
+			reason = "no stored content_data"
+		} else if missing := missingRequiredLLMFields(comp.InputSchema, s.contentData); len(missing) > 0 {
+			reason = fmt.Sprintf("stored content_data missing required field(s) %v", missing)
+		}
 		if reason != "" {
 			... escalateRerenderToWriter(...) ; out["escalated"] = true ; return out, nil
 		}
 	}

NOTE: article-body protection is UNCHANGED. article-body declares a required
source:"llm" field, so missingRequiredLLMFields(schema, nil) is non-empty, the
guard still runs, and both original escalation branches (a) absent content_data
and (b) present-but-missing-required-field behave exactly as before.
